const item = $input.item.json;
const existingVideoId = (item['HeyGen_Video_ID'] || '').trim();
const status = item['Status'] || '';
const alreadyHasId = existingVideoId.length > 0;
const statusBlocked = status === 'Video Ready' || status === 'Video Processing' || status === 'Failed';
const alreadyProcessed = alreadyHasId || statusBlocked;
return { json: { ...item, already_processed: alreadyProcessed, existing_video_id: existingVideoId, already_has_id: alreadyHasId, status_blocked: statusBlocked } };

const item = $input.item.json;
const cfg = item.cfg || {};
const a = cfg.avatar || {};
const rawCategory = (item['Category'] && typeof item['Category'] === 'object') ? (item['Category'].name || '') : (item['Category'] || '');
const contentType = item['Content Type'] || 'Video';
const platform    = item['Platform']     || 'YouTube';
const ratioField  = item['Ratio'] || '';
const categoryMap = a.category_map || { 'News': 'News', 'Business': 'News', 'Tech': 'News', 'Entertainment': 'News', 'Other': 'News', 'General': 'News', 'Education': 'Education', 'Health': 'Education', 'Lifestyle': 'Education', 'Motivation': 'Education', 'Comedy': 'Education', 'Product': 'Product', 'Product Intro': 'Product' };
const theme = categoryMap[rawCategory] || a.default_theme || 'News';
let videoWidth, videoHeight, isShortForm;
if (ratioField === 'Portrait') { videoWidth = 1080; videoHeight = 1920; isShortForm = true; } else if (ratioField === 'Landscape') { videoWidth = 1920; videoHeight = 1080; isShortForm = false; } else { isShortForm = platform === 'TikTok' || platform === 'Instagram' || contentType === 'Short'; videoWidth = isShortForm ? 1080 : 1920; videoHeight = isShortForm ? 1920 : 1080; }
return { json: { cfg: cfg, record_id: item.id || '', topic: item['Topic'] || '', script: item['Script'] || '', screenshots_needed: item['Screenshots_Needed'] || '', category: theme, raw_category: rawCategory, platform: platform, content_type: contentType, ratio: ratioField, video_width: videoWidth, video_height: videoHeight, is_short_form: isShortForm, has_script: !!(item['Script'] && item['Script'].trim().length > 10) } };

const prev = $('3. Has Valid Script?').item.json;
const a = (prev.cfg || {}).avatar || {};
let cleanScript = prev.script || '';
cleanScript = cleanScript.replace(/\*\*(.*?)\*\*/g, '$1').replace(/\*(.*?)\*/g, '$1').replace(/_(.*?)_/g, '$1');
cleanScript = cleanScript.replace(/\[HOOK\][:\s-]*/gi, '').replace(/\[BODY\][:\s-]*/gi, '').replace(/\[CTA\][:\s-]*/gi, '').replace(/\[BRACKETS\][:\s-]*/gi, '').replace(/\[INTRO\][:\s-]*/gi, '').replace(/\[OUTRO\][:\s-]*/gi, '').replace(/\[TRANSITION\][:\s-]*/gi, '').replace(/\[SCENE[^\]]*\][:\s-]*/gi, '').replace(/\[B-?ROLL[^\]]*\][:\s-]*/gi, '').replace(/\[TEXT[^\]]*\][:\s-]*/gi, '').replace(/\[OVERLAY[^\]]*\][:\s-]*/gi, '').replace(/\[.*?\]/g, '');
cleanScript = cleanScript.replace(/TAGS?:\s*[^\n]*/gi, '');
cleanScript = cleanScript.replace(/\\n/g, ' ').replace(/\n/g, ' ').replace(/\r/g, ' ').replace(/\s+/g, ' ').trim();
const CHAR_LIMIT = a.char_limit || 5000;
const SENTENCE_FLOOR = a.sentence_floor || 4000;
if (cleanScript.length > CHAR_LIMIT) { const truncated = cleanScript.substring(0, CHAR_LIMIT); const lastPeriod = Math.max(truncated.lastIndexOf('. '), truncated.lastIndexOf('! '), truncated.lastIndexOf('? ')); cleanScript = lastPeriod > SENTENCE_FLOOR ? truncated.substring(0, lastPeriod + 1) : truncated; }
return { json: { ...prev, script: cleanScript } };

// HG-3: HeyGen /v3/users/me. Wallet balance in USD replaces the retired /v2/user/remaining_quota.
const r = $input.item.json || {};
const recordData = $('3c. Clean Script').item.json;
const a = (recordData.cfg || {}).avatar || {};
const d = r.data || {};
const w = d.wallet || null;
const bal = (w && typeof w.remaining_balance === 'number') ? w.remaining_balance : null;
const MIN_USD = (typeof a.min_balance_usd === 'number') ? a.min_balance_usd : 10;
const WARN_USD = (typeof a.warn_balance_usd === 'number') ? a.warn_balance_usd : 30;
// Fail closed: no readable balance means nothing is submitted.
const hasEnough = bal !== null && bal >= MIN_USD;
let balanceError = '';
if (bal === null) {
  const e = r.error;
  balanceError = e ? String((e && (e.message || e.code)) || JSON.stringify(e)).substring(0, 300) : ('No wallet balance in the HeyGen response (billing_type: ' + (d.billing_type || 'unknown') + ')');
}
return { json: { ...recordData, balance_usd: bal, balance_currency: (w && w.currency) || '', min_balance_usd: MIN_USD, has_enough_credits: hasEnough, credits_warning: bal !== null && bal < WARN_USD, auto_reload: !!(w && w.auto_reload && w.auto_reload.enabled), balance_error: balanceError } };

