(function() {
  const cfg = $json.cfg || {};
  const a = cfg.avatar || {};
  const category = $json.category || 'News';
  const ratio    = $json.ratio    || '';

  if (!ratio) {
    throw new Error('Ratio field is required but is empty. Set Ratio to Landscape or Portrait on the Reel Engine record before submitting.');
  }

  const avatarPools = a.avatar_pools || {};
  const orientation = ratio === 'Portrait' ? 'portrait' : 'landscape';
  const themePool = avatarPools[category] || avatarPools['News'] || {};
  const pool = themePool[orientation] || [];

  if (!pool.length) {
    throw new Error('No avatar pool configured for category "' + category + '" / ' + orientation + ' on client ' + (cfg.client_name || 'unknown') + '. Set avatar.avatar_pools in Config_JSON.');
  }

  const avatarId = pool[Math.floor(Math.random() * pool.length)];
  const aspectRatio = ratio === 'Portrait' ? '9:16' : '16:9';

  // Delivery controls. All optional and config-driven so tone can be tuned per client
  // without editing this node. Only keys that are actually set are sent to HeyGen.
  const voiceSettings = {
    speed: (a.voice_speed !== undefined && a.voice_speed !== null) ? a.voice_speed : 1.0
  };
  if (a.voice_emotion) { voiceSettings.emotion = a.voice_emotion; }
  if (a.voice_pitch !== undefined && a.voice_pitch !== null) { voiceSettings.pitch = a.voice_pitch; }
  if (a.voice_locale) { voiceSettings.locale = a.voice_locale; }

  const body = {
    type: 'avatar',
    avatar_id: avatarId,
    script: $json.script,
    voice_id: a.voice_id || '',
    title: $json.topic,
    resolution: a.resolution || '1080p',
    aspect_ratio: aspectRatio,
    engine: { type: a.engine_type || 'avatar_v' },
    voice_settings: voiceSettings,
    callback_url: a.callback_url || ''
  };

  // Avatar IV supports motion/gesture direction. Ignored by Avatar V, which is filmed footage.
  if (a.avatar_style) { body.avatar_style = a.avatar_style; }
  if (a.motion_prompt) { body.motion_prompt = a.motion_prompt; }
  if (a.scale !== undefined && a.scale !== null) { body.scale = a.scale; }

  return JSON.stringify(body);
})()
}}

