const response = $input.item.json || {};
const recordData = $('2. Extract + Set Dimensions').item.json;
const videoId = String((response.data && response.data.video_id) || response.video_id || '').trim();
// HG-2: keep the HeyGen error when no video_id comes back, so it can be written to the notes.
let submitError = '';
if (!videoId) {
  const e = response.error || response.message || response;
  submitError = (typeof e === 'string') ? e : (e.message || e.description || JSON.stringify(e));
  submitError = String(submitError).substring(0, 800);
}
return { json: { cfg: recordData.cfg, record_id: recordData.record_id, heygen_video_id: videoId, submit_error: submitError, topic: recordData.topic, script: recordData.script, screenshots_needed: recordData.screenshots_needed || '', category: recordData.category, content_type: recordData.content_type, platform: recordData.platform } };

const OUTPUT_TYPE = 'avatar';

function parseJson(raw, label) {
  if (!raw) return {};
  try {
    const v = JSON.parse(raw);
    if (v && typeof v === 'object' && !Array.isArray(v)) return v;
    return {};
  } catch (e) { console.log('[0b] Invalid Config_JSON on ' + label + ': ' + e.message); return {}; }
}

const outputs = $input.all().map(i => i.json);
const clients = $('0a. Load Clients').all().map(i => i.json);

const outByKey = {};
for (const o of outputs) {
  const key = (o['Key'] || '').trim().toLowerCase();
  if (key) outByKey[key] = o;
}

const out = [];
for (const c of clients) {
  const name = c['Client_Name'];
  if (!name) continue;
  if (c['Video_Enabled'] !== true) continue;
  if (!c['Video_Base_ID']) continue;

  const o = outByKey[(name + '::' + OUTPUT_TYPE).toLowerCase()] || null;
  const merged = { ...parseJson(c['Config_JSON'], name), ...parseJson(o ? o['Config_JSON'] : '', name + '::' + OUTPUT_TYPE) };
  if (!o) console.log('[0b] No Client_Outputs row for ' + name + '::' + OUTPUT_TYPE);

  // HG-2: daily HeyGen submit cap per client. CONTROL > Clients > Daily_Video_Cap. Blank or invalid = 3. 0 = no videos.
  const capRaw = c['Daily_Video_Cap'];
  const dailyVideoCap = (typeof capRaw === 'number' && capRaw >= 0) ? Math.floor(capRaw) : 3;

  out.push({ json: {
    ...merged,
    client_name:            name,
    video_base_id:          c['Video_Base_ID'],
    brand_name:             c['Brand_Name'] || name,
    timezone:               c['Timezone'] || 'Asia/Manila',
    output_type:            OUTPUT_TYPE,
    daily_video_cap:        dailyVideoCap,
    drive_shared_drive_id:  c['Drive_Shared_Drive_ID'] || '',
    drive_folder_id:        o ? (o['Drive_Folder_ID'] || '') : ''
  } });
}
console.log('[0b] Clients to process: ' + out.length);
return out;

// HG-2: config now comes from 0g, which carries the client config plus today's submit count.
let cfg = null;
try { cfg = $('0g. Attach Daily Count').first().json; } catch (e) { cfg = null; }
if (!cfg || !cfg.video_base_id) { throw new Error('Could not resolve client config for this iteration.'); }
// started_at is captured here so the notes block can report how long the run took.
return { json: { ...$input.item.json, cfg, started_at: new Date().toISOString() } };

const fresh = $input.item.json || {};
const d = $('2. Extract + Set Dimensions').item.json;
const a = (d.cfg || {}).avatar || {};
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const sep = a.notes_separator || '==============================';
const TAG = a.stage_tag || 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
let runtime = 'unknown';
try { const s = Date.parse($('1c. Attach Config').first().json.started_at || ''); if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; } } catch (e) {}
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const block = sep + '\n' + TAG + '\nUpdated: ' + stamp + '\nStage: Error - Ratio missing' + '\nRun time: ' + runtime + '\nDetail: Ratio field is empty. Set Ratio to Landscape or Portrait to resume.';
return { json: { ...d, reel_notes_final: (base ? base + '\n\n' : '') + block } };

const fresh = $input.item.json || {};
const d = $('3e. Enough Credits?').item.json;
const a = (d.cfg || {}).avatar || {};
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const sep = a.notes_separator || '==============================';
const TAG = a.stage_tag || 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
let runtime = 'unknown';
try { const s = Date.parse($('1c. Attach Config').first().json.started_at || ''); if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; } } catch (e) {}
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const balLine = (d.balance_usd === null || d.balance_usd === undefined) ? ('unknown' + (d.balance_error ? ' (' + d.balance_error + ')' : '')) : ('$' + Number(d.balance_usd).toFixed(2));
const block = sep + '\n' + TAG + '\nUpdated: ' + stamp + '\nStage: Paused - low HeyGen credits' + '\nRun time: ' + runtime + '\nHeyGen wallet balance: ' + balLine + ' (minimum $' + d.min_balance_usd + ')' + '\nAuto reload: ' + (d.auto_reload ? 'on' : 'off') + '\nDetail: Top up the HeyGen API wallet to resume.';
return { json: { ...d, reel_notes_final: (base ? base + '\n\n' : '') + block } };

const fresh = $input.item.json || {};
const d = $('5f. Restore HeyGen Context').item.json;
const a = (d.cfg || {}).avatar || {};
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const sep = a.notes_separator || '==============================';
const TAG = a.stage_tag || 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
let triggered = '';
let runtime = 'unknown';
try {
  const raw = $('1c. Attach Config').first().json.started_at || '';
  triggered = raw ? raw.substring(0, 16).replace('T', ' ') : '';
  const s = Date.parse(raw);
  if (s) { const secs = Math.max(0, Math.round((Date.now() - s) / 1000)); runtime = Math.floor(secs / 60) + 'm ' + (secs % 60) + 's'; }
} catch (e) {}
const jobId = d.heygen_video_id || '';
const tpl = a.task_url_template || 'https://app.heygen.com/videos/{video_id}';
const jobUrl = jobId ? String(tpl).replace('{video_id}', jobId) : '';
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
// HG-2: one line per HeyGen submit. More than one line = the record was rendered more than once.
const NL = String.fromCharCode(10);
const freshHist = (f && typeof f.HeyGen_ID_History === 'string') ? f.HeyGen_ID_History.trim() : '';
const history = (freshHist ? freshHist + NL : '') + new Date().toISOString() + ' | ' + jobId;
const idCount = history.split(NL).filter(l => l.trim()).length;
const block = sep + '\n' + TAG + '\nTriggered: ' + triggered + '\nUpdated: ' + stamp + '\nRun time to submit: ' + runtime + '\nStage: Submitted to HeyGen' + '\nHeyGen Job ID: ' + jobId + (jobUrl ? '\nHeyGen Task URL: ' + jobUrl : '') + (idCount > 1 ? '\nWarning: HeyGen submit number ' + idCount + ' for this record' : '');
return { json: { ...d, heygen_id_history: history, heygen_id_count: idCount, reel_notes_final: (base ? base + '\n\n' : '') + block } };

const cfg = $('0c. Client Loop').first(1).json;
const rows = $input.all().map(i => i.json || {});
const err = rows.find(r => r && r.error);
const ids = rows.filter(r => r && r.id).map(r => r.id);
let countError = '';
if (err) { const e = err.error; countError = String((e && e.message) || e).substring(0, 300); }
return [{ json: { ...cfg, submitted_today: err ? null : ids.length, count_error: countError }, pairedItem: { item: 0 } }];

// HG-2 guardrail (Global): decide from LIVE Airtable data which records may go to HeyGen.
const READY = 'Ready for Video Generation';
const CAP_LINE = 'Waiting: daily video cap reached';
const TRG = 'VIDEO TRIGGER (WF06)';
const ORCH = 'PRODUCTION ORCHESTRATOR';
const NL = String.fromCharCode(10);
const flat = r => (r && r.fields && typeof r.fields === 'object') ? { id: r.id, ...r.fields } : (r || {});
const sel = v => (v && typeof v === 'object') ? (v.name || '') : (v || '');
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const ctxItems = $('3f. Credits OK?').all(0);
const liveItems = $input.all().map(i => flat(i.json));

// Who moved a reel to Ready for Video Generation? The Production Orchestrator (Manus) logs every move in its own notes block.
// Manus = it logged a move to Ready for Video Generation after the last HeyGen submit. Anything else = set by hand.
const lastOrchMove = (notes, sep, tz) => {
  const lines = String(notes || '').split(NL);
  let inBlock = false; let curDate = ''; let best = null;
  for (let i = 0; i < lines.length; i++) {
    const l = lines[i].trim();
    if (l === sep) { inBlock = ((lines[i + 1] || '').trim() === ORCH); curDate = ''; continue; }
    if (!inBlock) continue;
    if (l.length === 10 && l[4] === '-' && l[7] === '-') { curDate = l; continue; }
    if (curDate && l.includes('-> ' + READY)) {
      const hm = l.slice(0, 5);
      const zone = (l.slice(6).split(' ')[0] || tz);
      let d = DateTime.fromISO(curDate + 'T' + hm, { zone });
      if (!d.isValid) d = DateTime.fromISO(curDate + 'T' + hm, { zone: tz });
      if (d.isValid && (!best || d > best)) best = d;
    }
  }
  return best;
};

const out = [];
let slots = null;
for (let k = 0; k < ctxItems.length; k++) {
  const ctx = ctxItems[k].json;
  const cfg = ctx.cfg || {};
  const a = cfg.avatar || {};
  const tz = cfg.timezone || 'Asia/Manila';
  const cap = (typeof cfg.daily_video_cap === 'number' && cfg.daily_video_cap >= 0) ? cfg.daily_video_cap : 3;
  const counted = (typeof cfg.submitted_today === 'number') ? cfg.submitted_today : null;
  if (slots === null) slots = (counted === null) ? 0 : Math.max(0, cap - counted);
  const today = $now.setZone(tz).toFormat('yyyy-MM-dd');
  const idx = liveItems.findIndex(r => r.id === ctx.record_id);
  const live = idx >= 0 ? liveItems[idx] : null;
  const liveStatus = live ? String(sel(live['Status'])) : '';
  const liveId = live ? String(live['HeyGen_Video_ID'] || '').trim() : '';
  const liveNotes = (live && typeof live['Reel_Notes'] === 'string') ? live['Reel_Notes'] : '';
  // T-44: both approvals are read from the live record.
  const approved = !!live && live['Production_Approval'] === true && String(sel(live['Script_Approval'])) === 'Approved';
  const sep = a.notes_separator || '==============================';
  const TAG = a.stage_tag || 'AVATAR (WF06)';
  const blockRe = tag => new RegExp('\\n*' + esc(sep) + '\\n' + esc(tag) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
  const base = liveNotes.replace(blockRe(TAG), '').replace(blockRe(TRG), '').trim();
  const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
  const orchAt = lastOrchMove(liveNotes, sep, tz);
  const prevSubmit = live && live['HeyGen_Submitted_At'] ? DateTime.fromISO(String(live['HeyGen_Submitted_At'])) : null;
  const byManus = !!(orchAt && (!prevSubmit || !prevSubmit.isValid || orchAt > prevSubmit));
  const movedBy = byManus ? 'Production Orchestrator (Manus), ' + orchAt.setZone(tz).toFormat('yyyy-MM-dd HH:mm') + ' ' + tz : 'Manual (set by hand, no Production Orchestrator entry for this move)';
  const trgBlock = [sep, TRG, 'Updated: ' + stamp, 'Moved to ' + READY + ' by: ' + movedBy].join(NL);
  const mk = lines => (base ? base + NL + NL : '') + trgBlock + NL + NL + sep + NL + TAG + NL + lines.join(NL);
  let action = 'submit';
  let reason = '';
  let notes = '';
  if (!live) {
    action = 'skip'; reason = 'Record could not be re-read live';
  } else if (liveStatus !== READY) {
    action = 'skip'; reason = 'Live status is ' + liveStatus + ', not ' + READY;
  } else if (liveId) {
    action = 'skip'; reason = 'Record already has HeyGen ID ' + liveId;
  } else if (!approved) {
    // T-44: not approved. Nothing is submitted, no cap slot is used, Status goes back to Verified.
    action = 'unapproved'; reason = 'Not approved: skipped';
    notes = mk(['Updated: ' + stamp, 'Stage: Skipped', 'Not approved: skipped']);
  } else if (counted === null) {
    action = 'skip'; reason = 'Daily submit count unavailable, nothing submitted: ' + (cfg.count_error || 'unknown error');
  } else if (slots <= 0) {
    const used = Math.max(counted, cap);
    reason = CAP_LINE + ' (' + used + ' of ' + cap + ' on ' + today + ')';
    // Write the waiting note once per day, not on every 1-minute run.
    const alreadyNoted = liveNotes.includes(CAP_LINE) && liveNotes.includes('Cap date: ' + today);
    action = alreadyNoted ? 'skip' : 'cap';
    notes = mk(['Updated: ' + stamp, 'Stage: ' + CAP_LINE, 'Cap date: ' + today, 'Submitted today: ' + used + ' of ' + cap, 'Detail: Record stays at ' + READY + '. It resumes on its own the next day or when Daily_Video_Cap is raised in CONTROL.']);
  } else {
    slots = slots - 1;
    notes = mk(['Updated: ' + stamp, 'Stage: Locked - submitting to HeyGen', 'Daily cap: ' + (cap - slots) + ' of ' + cap]);
  }
  out.push({ json: { ...ctx, gate_action: action, gate_reason: reason, moved_by: byManus ? 'manus' : 'manual', daily_video_cap: cap, locked_at: new Date().toISOString(), reel_notes_final: notes }, pairedItem: { item: idx >= 0 ? idx : Math.min(k, Math.max(0, liveItems.length - 1)) } });
}
return out;

const fresh = $input.item.json || {};
const d = $('5. Preserve Data + Extract Video ID').item.json;
const a = (d.cfg || {}).avatar || {};
const f = (fresh.fields && typeof fresh.fields === 'object') ? fresh.fields : fresh;
const freshNotes = (f && typeof f.Reel_Notes === 'string') ? f.Reel_Notes : '';
const NL = String.fromCharCode(10);
const sep = a.notes_separator || '==============================';
const TAG = a.stage_tag || 'AVATAR (WF06)';
const esc = t => t.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const re = new RegExp('\\n*' + esc(sep) + '\\n' + esc(TAG) + '[\\s\\S]*?(?=(\\n' + esc(sep) + '\\n)|$)', 'g');
const base = freshNotes.replace(re, '').trim();
const stamp = new Date().toISOString().substring(0, 16).replace('T', ' ');
const block = [sep, TAG, 'Updated: ' + stamp, 'Stage: Error - HeyGen submit failed', 'HeyGen error: ' + (d.submit_error || 'No video_id in the HeyGen response'), 'Detail: HeyGen returned no video ID, so none was written. Fix the cause, then set Status back to Ready for Video Generation to retry.'].join(NL);
return { json: { cfg: d.cfg, record_id: d.record_id, reel_notes_final: (base ? base + NL + NL : '') + block } };
